#!/usr/bin/env bash
# Shared by root-owned server tools; never enable xtrace around environment values.
set +x
set -euo pipefail
require_root() { [[ $EUID -eq 0 ]] || { printf '%s\n' 'Run with sudo.' >&2; exit 1; }; }
load_env() {
  [[ -f /etc/workflow/env && ! -L /etc/workflow/env && $(stat -c '%u:%a' /etc/workflow/env) == '0:600' ]] || { printf '%s\n' 'Expected /etc/workflow/env owned by root with mode 600.' >&2; return 1; }
  set -a
  # File is generated by setup-secrets.sh, owned by root and not writable by the app.
  source /etc/workflow/env
  set +a
}
lock_ops() {
  mkdir -p /run/lock
  # A systemd job and release.sh share the same open file description/lock.
  # Reopening it would deadlock the child against its supervising worker.
  if [[ ! /proc/self/fd/9 -ef /run/lock/workflow-maintenance.lock ]]; then
    exec 9>/run/lock/workflow-maintenance.lock
  fi
  flock -x 9
}
db() { mariadb --protocol=socket --user=root --batch --skip-column-names "$@"; }
schema_version() {
  local database=${1:-mini_erp}
  [[ $database =~ ^[A-Za-z0-9_]+$ ]] || return 1
  if [[ $(db -e "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='$database' AND table_name='flyway_schema_history'") == 0 ]]; then printf '0\n';
  else db "$database" -e 'SELECT COALESCE((SELECT version FROM flyway_schema_history WHERE success=1 AND version IS NOT NULL ORDER BY installed_rank DESC LIMIT 1),"0")'; fi
}
prune_backups() {
  local directory=$1 file count=0 removed=0
  while IFS= read -r file; do
    count=$((count+1))
    if ((count>7)); then
      rm -f -- "$directory/$file" "$directory/$file.sha256" "$directory/$file.version" "$directory/$file.counts.tsv"
      removed=$((removed+1))
    fi
  done < <(find "$directory" -maxdepth 1 -type f -name '*.sql.gz' -printf '%f\n' | LC_ALL=C sort -r)
  printf 'BACKUP_RETAIN sets=%s removed_sets=%s\n' "$((count-removed))" "$removed"
}
backup_now() (
  umask 077
  # A distinct lock lets measurements detect any backup, including pre-deploy dumps.
  mkdir -p /run/lock
  exec 8>/run/lock/workflow-backup.lock
  flock -x 8
  install -d -o root -g root -m 700 /var/backups/workflow
  local_path=/var/backups/workflow
  name="$(date -u +%Y%m%dT%H%M%S.%NZ).sql.gz"
  partial=$(mktemp "$local_path/.partial.XXXXXX")
  trap 'rm -f -- "$partial"' EXIT
  began=$SECONDS
  mariadb-dump --protocol=socket --user=root --single-transaction --quick --routines --triggers --events --hex-blob --default-character-set=utf8mb4 mini_erp | gzip >"$partial"
  gzip -t "$partial"
  mv -- "$partial" "$local_path/$name"
  (cd "$local_path"; sha256sum "$name" >"$name.sha256")
  schema_version >"$local_path/$name.version"
  prune_backups "$local_path"
  printf 'BACKUP file=%s bytes=%s elapsed_s=%s\n' "$name" "$(stat -c %s "$local_path/$name")" "$((SECONDS-began))"
)
latest_backup() { find /var/backups/workflow -maxdepth 1 -type f -name '*.sql.gz' -printf '%f\n' | LC_ALL=C sort | tail -1; }
valid_release() { [[ $1 =~ ^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{7}$ ]]; }
health_snapshot() {
  local snapshot key value
  snapshot=$(systemctl show workflow --property=NRestarts --property=ActiveState) || return 1
  health_restarts=''; health_active=''
  while IFS='=' read -r key value; do
    case $key in NRestarts) health_restarts=$value;; ActiveState) health_active=$value;; esac
  done <<<"$snapshot"
  [[ $health_restarts =~ ^[0-9]+$ && $health_active =~ ^[a-z-]+$ ]]
}
health_wait() {
  local limit=$1 migration=$2 began=$SECONDS domain initial until
  local health_restarts health_active
  [[ $limit =~ ^[1-9][0-9]*$ && $migration =~ ^(YES|NO)$ ]] || return 2
  until=$((SECONDS+limit)); domain=$(cat /etc/workflow/domain)
  if ! health_snapshot; then
    printf 'HEALTH_WAIT limit_s=%s migration=%s result=STATUS_UNAVAILABLE elapsed_s=%s\n' "$limit" "$migration" "$((SECONDS-began))"; return 1
  fi
  initial=$health_restarts
  while (( SECONDS < until )); do
    if ! health_snapshot; then
      printf 'HEALTH_WAIT limit_s=%s migration=%s result=STATUS_UNAVAILABLE elapsed_s=%s\n' "$limit" "$migration" "$((SECONDS-began))"; return 1
    fi
    if [[ $health_active == failed ]] || ((health_restarts>initial)); then
      printf 'HEALTH_WAIT limit_s=%s migration=%s result=APP_FAILED elapsed_s=%s\n' "$limit" "$migration" "$((SECONDS-began))"; return 1
    fi
    local remaining=$((until-SECONDS)) request_limit=2
    ((remaining>0)) || break # curl --max-time 0 would mean no timeout.
    ((remaining<request_limit)) && request_limit=$remaining
    if curl --silent --fail --max-time "$request_limit" --resolve "$domain:443:127.0.0.1" "https://$domain/healthz" | jq -e '.status == "UP"' >/dev/null 2>&1; then
      # A received UP must be decided now, even if processing crossed the deadline.
      # Still reject a process that restarted/failed while the response was in flight.
      if ! health_snapshot; then
        printf 'HEALTH_WAIT limit_s=%s migration=%s result=STATUS_UNAVAILABLE elapsed_s=%s\n' "$limit" "$migration" "$((SECONDS-began))"; return 1
      fi
      if [[ $health_active == failed ]] || ((health_restarts>initial)); then
        printf 'HEALTH_WAIT limit_s=%s migration=%s result=APP_FAILED elapsed_s=%s\n' "$limit" "$migration" "$((SECONDS-began))"; return 1
      fi
      printf 'HEALTH_WAIT limit_s=%s migration=%s result=UP elapsed_s=%s\n' "$limit" "$migration" "$((SECONDS-began))"; return 0
    fi
    sleep 1
  done
  printf 'HEALTH_WAIT limit_s=%s migration=%s result=TIMEOUT elapsed_s=%s\n' "$limit" "$migration" "$((SECONDS-began))"
  return 1
}
point_link() { local base=$1 release=$2; rm -f "$base/.current.next"; ln -s "$base/releases/$release" "$base/.current.next"; mv -Tf "$base/.current.next" "$base/current"; }
